    x = narginchk(1, 2);
    y = nargoutchk(1, 2);
end
";
        let diags = check_source(source, "foo.m");
        let nchkos = filter_by_id(&diags, "NCHKOS");
        assert_eq!(
            nchkos.len(),
            2,
            "NCHKOS should fire for narginchk/nargoutchk on RHS"
        );
    }

