                    if self.is_check_enabled("MCSCC") {
                        let pos = call_node.start_position();
                        diagnostics.push(Diagnostic {
                            rule_id: "MCSCC",
                            message: "To call the superclass constructor, the subclass constructor name must match the subclass name"
