import json, re, glob

dirs = ["crates/mlt_rules/src/language_spec", "crates/mlt_rules/src/incomplete_analysis"]

def norm_src(s):
    # remove line-continuation backslash-newline-whitespace
    s = re.sub(r'\\\n\s*', ' ', s)
    s = re.sub(r'\s+', ' ', s)
    return s

src = ""
for d in dirs:
    for f in glob.glob(d + "/*.rs"):
        src += norm_src(open(f).read()) + "\n"

def build_regex(mw):
    # escape, replace VAR_* placeholders with [^"]*
    parts = re.split(r'(VAR_[A-Z_]+)', mw)
    rx = ""
    for p in parts:
        if re.fullmatch(r'VAR_[A-Z_]+', p):
            rx += r'[^"]*'
        else:
            rx += re.escape(p)
    return re.compile(rx)

problems = []
for fn in ["language_spec", "incomplete_analysis"]:
    for e in json.load(open(f".playwright-mcp/targets/{fn}.json")):
        mw = e["mw"]
        if not mw:
            continue
        rx = build_regex(mw)
        if not rx.search(src):
            problems.append((fn, e["id"], mw))

print("Checks whose MW text NOT found (potential miss):")
for p in problems:
    print(p)
print("total:", len(problems))
